const base = $('When Executed by Another Workflow').item.json;
const listingContent = $items('Groq Listing JSON',0,0)[0].json.choices[0].message.content;
const socialContent = $items('Groq Social Copy',0,0)[0].json.choices[0].message.content;
let listing, social;
try { listing = JSON.parse(listingContent); } catch(e){ const m=listingContent.match(/\{[\s\S]*\}/); listing = m?JSON.parse(m[0]):{}; }
try { social = JSON.parse(socialContent); } catch(e){ const m=socialContent.match(/\{[\s\S]*\}/); social = m?JSON.parse(m[0]):{}; }

function ensureDir(p){ /* n8n Write File will auto create */ }

const files = {
  'listing.txt': `TITLE: ${listing.long_title}\nSHORT: ${listing.short_description}\nSLUG: ${listing.seo_slug}\nPRICE: ${base.evaluation?.suggested_price}\n`,
  'gumroad.md': `${listing.long_title}\n\n${listing.description_gumroad_md}\n\nTags: ${listing.seo_tags?.join(', ')}`,
  'etsy.md': `${listing.title}\n\n${listing.description_etsy}`,
  'shopify.html': `<h2>${listing.long_title}</h2><p>${listing.short_description}</p><div>${listing.description_shopify}</div>`,
  'payhip.txt': listing.description_payhip,
  'seo.txt': `Slug: ${listing.seo_slug}\nTitle: ${listing.long_title} | ${base.brand_name}\nMeta: ${listing.short_description}\nKeywords: ${listing.keywords_csv}\nEtsy: ${listing.etsy_tags?.join(', ')}`,
  'hashtags.txt': (listing.hashtags||[]).map(t=>'#'+t.replace(/^#/,'')).join(' '),
  'twitter.txt': `${social.twitter_post}\n\n--- THREAD ---\n${social.launch_tweet_thread}`,
  'linkedin.txt': social.linkedin_post,
  'facebook.txt': social.facebook_caption,
  'pinterest.txt': `Title: ${social.pinterest_pin_title}\nDesc: ${social.pinterest_pin_desc}`,
  'instagram.txt': social.instagram_caption,
  'email.txt': `Subject: ${social.email_campaign?.subject}\nPreview: ${social.email_campaign?.preview}\n\n${social.email_campaign?.body}`,
  'listing.json': JSON.stringify({ ...listing, ...social, meta: { brand_name: base.brand_name, title: base.title, slug: listing.seo_slug||base.slug, price: base.evaluation?.suggested_price, avatar: base.avatar, outcome: base.dream_outcome } }, null, 2)
};

return [{ json: { ...base, listing, social, publishing_files: files } }];

const data = $input.item.json;
const slug = data.slug;
const files = data.publishing_files;
// Output individual items for Write File loop
return Object.entries(files).map(([filename, content])=>({ json: { slug, filename, content } }));
